script:
(function () {
  'use strict';
  // Mutual fund value after fees, simulated month by month:
  //   purchase: each deposit is reduced by the front-end sales charge (load);
  //   each month: balance grows at the monthly rate equivalent to the gross annual return,
  //     (1 + r)^(1/12) - 1, then the expense ratio / 12 is deducted from the balance,
  //     then the month's net deposit is added (end of month);
  //   each year end: the flat account fee is deducted;
  //   at sale: deferred sales charge = rate x min(total invested, value).
  // "Value with no fees" runs the same plan with every fee set to zero; cost of fees is the gap.
  // Net annual return is the money-weighted return (IRR of the monthly deposits and the ending
  // value), annualized as (1 + monthly)^12 - 1.
  // Verified: with no fees, $10,000 at 6% for 10 years = 10,000 x 1.06^10 = $17,908.48;
  // $0 initial + $100/month at a 12.6825% annual rate (1% a month) for 1 year = $1,268.25
  // (annuity factor 12.6825); a 2% load and 0.5% expense ratio on $10,000 at 0% for 1 year
  // = 9,800 x (1 - 0.005/12)^12 = $9,751.11; net return with no fees equals the gross return.
  // Cross-check: calculator.net's default ($20,000 + $1,000/month, 5%, 5 years, 2% load,
  // 0.5% expenses) shows $90,077.09 and $1,323.40 of expenses; this model gives $90,011.17
  // and $1,328.78 (within 0.1%; the sites time growth and fee deductions differently).
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });

  // --- calc start
  function simulate(p) {
    var rm = Math.pow(1 + p.rate, 1 / 12) - 1;
    var load = p.load, er = p.expense;
    var bal = p.initial * (1 - load), plain = p.initial;
    var invested = p.initial, loadPaid = p.initial * load, expensePaid = 0, accountPaid = 0, deferredPaid = 0;
    var rows = [];
    for (var m = 1; m <= p.years * 12; m++) {
      bal *= 1 + rm;
      var exp = bal * er / 12;
      bal -= exp;
      expensePaid += exp;
      bal += p.monthly * (1 - load);
      loadPaid += p.monthly * load;
      invested += p.monthly;
      plain = plain * (1 + rm) + p.monthly;
      if (m % 12 === 0) {
        var fee = Math.min(p.accountFee, Math.max(bal, 0));
        bal -= fee;
        accountPaid += fee;
        if (m === p.years * 12) {
          deferredPaid = p.deferred * Math.max(0, Math.min(invested, bal));
          bal -= deferredPaid;
        }
        rows.push({ year: m / 12, invested: invested, fees: loadPaid + expensePaid + accountPaid + deferredPaid, balance: bal, plain: plain });
      }
    }
    return { ending: bal, plain: plain, invested: invested, loadPaid: loadPaid, expensePaid: expensePaid,
             accountPaid: accountPaid, deferredPaid: deferredPaid, rows: rows };
  }

  // Monthly money-weighted return: solves P(1+i)^n + M * sum (1+i)^(n-t) = ending by bisection.
  function netAnnualReturn(initial, monthly, months, ending) {
    if (ending <= 0) return -1;
    function fv(i) {
      var v = initial;
      for (var t = 1; t <= months; t++) v = v * (1 + i) + monthly;
      return v - ending;
    }
    var lo = -0.99, hi = 1;
    if (fv(lo) > 0 || fv(hi) < 0) return NaN;
    for (var k = 0; k < 200; k++) {
      var mid = (lo + hi) / 2;
      if (fv(mid) > 0) hi = mid; else lo = mid;
      if (hi - lo < 1e-13) break;
    }
    return Math.pow(1 + (lo + hi) / 2, 12) - 1;
  }
  // --- calc end

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }

  function pct(x) {
    return (x * 100).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + '%';
  }

  var OUT = ['mfEnding', 'mfInvested', 'mfFees', 'mfCost', 'mfLoadPaid', 'mfExpensePaid', 'mfAccountPaid',
             'mfDeferredPaid', 'mfNoFee', 'mfGain', 'mfNetReturn'];

  function update() {
    var p = {
      initial: num('mfInitial'), monthly: num('mfMonthly'), rate: num('mfReturn'), years: Math.round(num('mfYears')),
      expense: num('mfExpense'), load: num('mfLoad'), deferred: num('mfDeferred'), accountFee: num('mfAccountFee')
    };
    var error = document.getElementById('mfError');
    var msg = '';
    if ([p.initial, p.monthly, p.accountFee].some(isNaN) || p.initial < 0 || p.monthly < 0 || p.accountFee < 0 ||
        p.initial > 1e10 || p.monthly > 1e9 || p.accountFee > 1e6) msg = 'Enter amounts of $0 or more.';
    else if (p.initial === 0 && p.monthly === 0) msg = 'Enter an initial investment, a monthly investment or both.';
    else if (isNaN(p.rate) || p.rate < -50 || p.rate > 50) msg = 'Enter an annual return between -50% and 50%.';
    else if (isNaN(p.years) || p.years < 1 || p.years > 60) msg = 'Enter a holding period of 1 to 60 years.';
    else if ([p.expense, p.load, p.deferred].some(function (v) { return isNaN(v) || v < 0 || v > 10; }))
      msg = 'Enter fee percentages between 0% and 10%.';
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) {
      OUT.forEach(function (id) { document.getElementById(id).textContent = '–'; });
      document.getElementById('mfSchedule').innerHTML = '';
      return;
    }
    p.rate /= 100; p.expense /= 100; p.load /= 100; p.deferred /= 100;
    var r = simulate(p);
    var fees = r.loadPaid + r.expensePaid + r.accountPaid + r.deferredPaid;
    var net = netAnnualReturn(p.initial, p.monthly, p.years * 12, r.ending);
    document.getElementById('mfEnding').textContent = money.format(r.ending);
    document.getElementById('mfInvested').textContent = money.format(r.invested);
    document.getElementById('mfFees').textContent = money.format(fees);
    document.getElementById('mfCost').textContent = money.format(r.plain - r.ending);
    document.getElementById('mfLoadPaid').textContent = money.format(r.loadPaid);
    document.getElementById('mfExpensePaid').textContent = money.format(r.expensePaid);
    document.getElementById('mfAccountPaid').textContent = money.format(r.accountPaid);
    document.getElementById('mfDeferredPaid').textContent = money.format(r.deferredPaid);
    document.getElementById('mfNoFee').textContent = money.format(r.plain);
    document.getElementById('mfGain').textContent = money.format(r.ending - r.invested);
    document.getElementById('mfNetReturn').textContent = isFinite(net) ? pct(net) : '–';
    document.getElementById('mfSchedule').innerHTML = r.rows.map(function (row) {
      return '<tr><td>' + row.year + '</td><td>' + money.format(row.invested) + '</td><td>' + money.format(row.fees) +
             '</td><td>' + money.format(row.balance) + '</td><td>' + money.format(row.plain) + '</td></tr>';
    }).join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('mfForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
